// Applies production security defaults to the native projects generated by
// `flutter create`. Idempotent: safe to run many times.
//
//   dart run <skill>/scripts/harden_platforms.dart [project_dir] [--secure-screens] [--dry-run]
//
// Uses only dart:io so it runs before `flutter pub get`.
// ignore_for_file: avoid_print

import 'dart:convert';
import 'dart:io';

final _changes = <String>[];
final _warnings = <String>[];
late final bool _dryRun;

void main(List<String> args) {
  _dryRun = args.contains('--dry-run');
  final secureScreens = args.contains('--secure-screens');
  final root = Directory(
    args.where((a) => !a.startsWith('--')).firstOrNull ?? '.',
  ).resolveSymbolicLinksSync();

  final android = Directory('$root/android');
  if (android.existsSync()) {
    _hardenManifest('$root/android/app/src/main/AndroidManifest.xml');
    _writeIfMissing(
      '$root/android/app/src/main/res/xml/network_security_config.xml',
      _networkSecurityConfig,
    );
    // Debug builds get their own, relaxed copy (Android merges the debug
    // source set over main): plain HTTP to a dev server on the LAN works on
    // a real phone, release stays HTTPS-only.
    _writeIfMissing(
      '$root/android/app/src/debug/res/xml/network_security_config.xml',
      _debugNetworkSecurityConfig,
    );
    _writeIfMissing(
      '$root/android/app/src/main/res/xml/data_extraction_rules.xml',
      _dataExtractionRules,
    );
    _writeIfMissing(
      '$root/android/app/src/main/res/xml/backup_rules.xml',
      _backupRules,
    );
    _hardenGradle(root);
    if (secureScreens) _secureScreens(root);
  } else {
    _warnings.add(
      'android/ not found. Run `flutter create --platforms=android,ios .` first.',
    );
  }

  if (Directory('$root/ios').existsSync()) {
    _hardenInfoPlist('$root/ios/Runner/Info.plist');
  }

  _ensureGitignore('$root/.gitignore', const [
    '# Signing secrets (never commit)',
    'android/key.properties',
    '*.jks',
    '*.keystore',
    '*.p12',
    '*.mobileprovision',
    'config/*.local.json',
    '# Obfuscation symbols (keep privately, needed to read crash stacks)',
    'build/symbols/',
  ]);

  print(_dryRun ? '\nDRY RUN — nothing written.' : '');
  print('Changes (${_changes.length}):');
  for (final c in _changes) {
    print('  + $c');
  }
  if (_warnings.isNotEmpty) {
    print('Warnings (${_warnings.length}):');
    for (final w in _warnings) {
      print('  ! $w');
    }
  }
}

// ---------------------------------------------------------------- Android

void _hardenManifest(String path) {
  final file = File(path);
  if (!file.existsSync()) {
    _warnings.add('Missing $path');
    return;
  }
  var xml = file.readAsStringSync();
  final original = xml;

  // Release builds have NO internet permission unless it is in the *main*
  // manifest (flutter create only adds it to debug/profile).
  if (!xml.contains('android.permission.INTERNET')) {
    xml = _insertAfterManifestTag(
      xml,
      '    <uses-permission android:name="android.permission.INTERNET"/>',
    );
    _changes.add('AndroidManifest: INTERNET permission in main manifest');
  }

  final attributes = <String, String>{
    'android:allowBackup': 'false',
    'android:fullBackupContent': '@xml/backup_rules',
    'android:dataExtractionRules': '@xml/data_extraction_rules',
    'android:usesCleartextTraffic': 'false',
    'android:networkSecurityConfig': '@xml/network_security_config',
  };
  final appTag = RegExp(r'<application\b[^>]*>').firstMatch(xml);
  if (appTag == null) {
    _warnings.add('AndroidManifest: <application> tag not found');
    return;
  }
  var tag = appTag.group(0)!;
  for (final MapEntry(:key, :value) in attributes.entries) {
    final existing = RegExp('$key="([^"]*)"').firstMatch(tag);
    if (existing == null) {
      tag = tag.replaceFirst(
        '<application',
        '<application\n        $key="$value"',
      );
      _changes.add('AndroidManifest: $key="$value"');
    } else if (existing.group(1) != value) {
      _warnings.add(
        'AndroidManifest: $key="${existing.group(1)}" kept (expected "$value"). Review manually.',
      );
    }
  }
  if (RegExp(r'android:debuggable="true"').hasMatch(xml)) {
    _warnings.add(
      'AndroidManifest: android:debuggable="true" must be removed.',
    );
  }
  xml = xml.replaceRange(appTag.start, appTag.end, tag);
  if (xml != original) _write(path, xml);
}

String _insertAfterManifestTag(String xml, String line) {
  final m = RegExp(r'<manifest\b[^>]*>').firstMatch(xml);
  if (m == null) return xml;
  return '${xml.substring(0, m.end)}\n$line${xml.substring(m.end)}';
}

void _hardenGradle(String root) {
  final kts = File('$root/android/app/build.gradle.kts');
  final groovy = File('$root/android/app/build.gradle');
  if (!kts.existsSync()) {
    if (groovy.existsSync()) _hardenGroovyGradle(groovy);
    return;
  }
  var text = kts.readAsStringSync();
  final original = text;

  if (!text.contains('key.properties')) {
    text = '$_ktsImports\n$text';
    // Statements may not precede the plugins {} block in .kts files.
    text = text.replaceFirstMapped(
      RegExp(r'^plugins\s*\{[\s\S]*?\n\}\n', multiLine: true),
      (m) => '${m[0]}\n$_ktsKeystoreLoading',
    );
    text = text.replaceFirstMapped(
      RegExp(r'\n(\s*)buildTypes\s*\{'),
      (m) => '\n${_ktsSigningConfigs.trimRight()}\n${m[0]}',
    );
    _changes.add(
      'build.gradle.kts: release signing from android/key.properties',
    );
  }

  final debugSigned = RegExp(
    r'release\s*\{[^}]*signingConfig\s*=\s*signingConfigs\.getByName\("debug"\)',
  );
  if (debugSigned.hasMatch(text)) {
    text = text.replaceFirst(debugSigned, 'release {\n$_ktsReleaseSigning');
    _changes.add(
      'build.gradle.kts: release no longer signed with the debug key',
    );
  }

  if (!text.contains('isMinifyEnabled')) {
    text = text.replaceFirstMapped(
      RegExp(r'release\s*\{'),
      (m) =>
          '${m[0]}\n            isMinifyEnabled = true\n            isShrinkResources = true',
    );
    _changes.add(
      'build.gradle.kts: R8 minify + resource shrinking for release',
    );
  }

  if (text != original) _write(kts.path, text);
}

/// Same as the .kts path, for projects still on the Groovy DSL.
void _hardenGroovyGradle(File file) {
  var text = file.readAsStringSync();
  final original = text;

  if (!text.contains('key.properties')) {
    final androidBlock = RegExp(
      r'^android\s*\{',
      multiLine: true,
    ).firstMatch(text);
    final buildTypes = RegExp(r'\n(\s*)buildTypes\s*\{').firstMatch(text);
    if (androidBlock == null || buildTypes == null) {
      _warnings.add(
        'android/app/build.gradle: android { } / buildTypes { } not found. '
        'Add release signing from key.properties manually (GOOGLE-PLAY-RELEASE.md).',
      );
      return;
    }
    // Later offset first, so the earlier one stays valid.
    text = text.replaceRange(
      buildTypes.start,
      buildTypes.start,
      '\n${_groovySigningConfigs.trimRight()}\n',
    );
    text = text.replaceRange(
      androidBlock.start,
      androidBlock.start,
      '$_groovyKeystoreLoading\n',
    );
    _changes.add('build.gradle: release signing from android/key.properties');
  }

  // Everything below edits buildTypes.release only (signingConfigs also has
  // a `release { }` block).
  final buildTypesAt = text.indexOf(RegExp(r'buildTypes\s*\{'));
  if (buildTypesAt < 0) return;
  final head = text.substring(0, buildTypesAt);
  var tail = text.substring(buildTypesAt);

  final debugSigned = RegExp(
    r'(release\s*\{[^}]*?)signingConfig\s*=?\s*signingConfigs\.debug\b',
  );
  if (debugSigned.hasMatch(tail)) {
    tail = tail.replaceFirstMapped(
      debugSigned,
      (m) => '${m[1]}$_groovyReleaseSigning',
    );
    _changes.add('build.gradle: release no longer signed with the debug key');
  }
  if (!tail.contains('minifyEnabled')) {
    tail = tail.replaceFirstMapped(
      RegExp(r'release\s*\{'),
      (m) =>
          '${m[0]}\n            minifyEnabled true\n            shrinkResources true',
    );
    _changes.add('build.gradle: R8 minify + resource shrinking for release');
  }
  text = head + tail;
  if (text != original) _write(file.path, text);
}

void _secureScreens(String root) {
  final dir = Directory('$root/android/app/src/main/kotlin');
  if (!dir.existsSync()) return;
  final activity = dir
      .listSync(recursive: true)
      .whereType<File>()
      .where((f) => f.path.endsWith('MainActivity.kt'))
      .firstOrNull;
  if (activity == null) return;
  final text = activity.readAsStringSync();
  if (text.contains('FLAG_SECURE')) return;
  final pkg = RegExp(
    r'^package\s+[\w.]+',
    multiLine: true,
  ).firstMatch(text)?.group(0);
  if (pkg == null || !text.contains('class MainActivity : FlutterActivity()')) {
    _warnings.add('MainActivity.kt was customized: add FLAG_SECURE manually.');
    return;
  }
  _write(activity.path, '''
$pkg

import android.os.Bundle
import android.view.WindowManager
import io.flutter.embedding.android.FlutterActivity

class MainActivity : FlutterActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        // Blocks screenshots, screen recording and the recent-apps preview.
        window.setFlags(
            WindowManager.LayoutParams.FLAG_SECURE,
            WindowManager.LayoutParams.FLAG_SECURE,
        )
        super.onCreate(savedInstanceState)
    }
}
''');
  _changes.add('MainActivity.kt: FLAG_SECURE');
}

// -------------------------------------------------------------------- iOS

void _hardenInfoPlist(String path) {
  final file = File(path);
  if (!file.existsSync()) return;
  final text = file.readAsStringSync();
  if (RegExp(
    r'<key>NSAllowsArbitraryLoads</key>\s*<true\s*/>',
  ).hasMatch(text)) {
    _warnings.add(
      'Info.plist: NSAllowsArbitraryLoads=true disables App Transport Security. Remove it.',
    );
  }
  if (!text.contains('ITSAppUsesNonExemptEncryption')) {
    _warnings.add(
      'Info.plist: add ITSAppUsesNonExemptEncryption (false if you only use HTTPS/OS crypto) '
      'to skip the export-compliance prompt on every upload.',
    );
  }
}

// ------------------------------------------------------------------ utils

void _ensureGitignore(String path, List<String> lines) {
  final file = File(path);
  final existing = file.existsSync() ? file.readAsStringSync() : '';
  final present = const LineSplitter()
      .convert(existing)
      .map((l) => l.trim())
      .toSet();
  final missing = lines.where((l) => !present.contains(l)).toList();
  if (missing.isEmpty) return;
  _write(path, '${existing.trimRight()}\n\n${missing.join('\n')}\n');
  _changes.add(
    '.gitignore: ${missing.where((l) => !l.startsWith('#')).join(', ')}',
  );
}

void _writeIfMissing(String path, String content) {
  if (File(path).existsSync()) return;
  _write(path, content);
  _changes.add('created ${path.split('/android/').last}');
}

void _write(String path, String content) {
  if (_dryRun) return;
  File(path)
    ..parent.createSync(recursive: true)
    ..writeAsStringSync(content);
}

const _networkSecurityConfig = '''<?xml version="1.0" encoding="utf-8"?>
<!-- HTTPS only; trust only system CAs (user-installed CAs cannot intercept
     traffic in release). Debug builds additionally trust user CAs so you can
     inspect traffic with a proxy during development. -->
<network-security-config>
    <base-config cleartextTrafficPermitted="false">
        <trust-anchors>
            <certificates src="system" />
        </trust-anchors>
    </base-config>
    <!-- Local development servers only (emulator host loopback). The app's
         Env check additionally refuses http:// in any release build. -->
    <domain-config cleartextTrafficPermitted="true">
        <domain includeSubdomains="false">10.0.2.2</domain>
        <domain includeSubdomains="false">localhost</domain>
        <domain includeSubdomains="false">127.0.0.1</domain>
    </domain-config>
    <debug-overrides>
        <trust-anchors>
            <certificates src="user" />
        </trust-anchors>
    </debug-overrides>
</network-security-config>
''';

const _debugNetworkSecurityConfig = '''<?xml version="1.0" encoding="utf-8"?>
<!-- DEBUG BUILDS ONLY (src/debug overrides src/main). Lets the app reach a
     development server over plain HTTP, including one on your local network
     from a real phone, and trusts user-installed CAs for proxy tools.
     Release builds use src/main/res/xml/network_security_config.xml. -->
<network-security-config>
    <base-config cleartextTrafficPermitted="true">
        <trust-anchors>
            <certificates src="system" />
            <certificates src="user" />
        </trust-anchors>
    </base-config>
</network-security-config>
''';

const _dataExtractionRules = '''<?xml version="1.0" encoding="utf-8"?>
<!-- Android 12+: exclude app data (tokens, caches) from cloud backup and
     device-to-device transfer. -->
<data-extraction-rules>
    <cloud-backup>
        <exclude domain="root" />
        <exclude domain="file" />
        <exclude domain="database" />
        <exclude domain="sharedpref" />
        <exclude domain="external" />
    </cloud-backup>
    <device-transfer>
        <exclude domain="root" />
        <exclude domain="file" />
        <exclude domain="database" />
        <exclude domain="sharedpref" />
        <exclude domain="external" />
    </device-transfer>
</data-extraction-rules>
''';

const _backupRules = '''<?xml version="1.0" encoding="utf-8"?>
<!-- Android 11 and lower: exclude everything from auto backup. -->
<full-backup-content>
    <exclude domain="root" />
    <exclude domain="file" />
    <exclude domain="database" />
    <exclude domain="sharedpref" />
    <exclude domain="external" />
</full-backup-content>
''';

const _groovyKeystoreLoading =
    '''// Release signing: android/key.properties (never committed).
def keystoreProperties = new Properties()
def keystorePropertiesFile = rootProject.file('key.properties')
if (keystorePropertiesFile.exists()) {
    keystorePropertiesFile.withInputStream { keystoreProperties.load(it) }
}
''';

const _groovySigningConfigs = '''
    signingConfigs {
        release {
            keyAlias keystoreProperties['keyAlias']
            keyPassword keystoreProperties['keyPassword']
            storeFile keystoreProperties['storeFile'] ? file(keystoreProperties['storeFile']) : null
            storePassword keystoreProperties['storePassword']
        }
    }
''';

const _groovyReleaseSigning =
    '''signingConfig keystorePropertiesFile.exists() ? signingConfigs.release : signingConfigs.debug
            if (!keystorePropertiesFile.exists()) {
                logger.warn("WARNING: android/key.properties missing - release is DEBUG-signed and cannot be uploaded to Google Play.")
            }''';

const _ktsImports = '''import java.io.FileInputStream
import java.util.Properties
''';

const _ktsKeystoreLoading =
    '''// Release signing: android/key.properties (never committed).
val keystoreProperties = Properties()
val keystorePropertiesFile = rootProject.file("key.properties")
if (keystorePropertiesFile.exists()) {
    FileInputStream(keystorePropertiesFile).use { keystoreProperties.load(it) }
}
''';

const _ktsSigningConfigs = '''
    signingConfigs {
        create("release") {
            keyAlias = keystoreProperties["keyAlias"] as String?
            keyPassword = keystoreProperties["keyPassword"] as String?
            storeFile = (keystoreProperties["storeFile"] as String?)?.let { file(it) }
            storePassword = keystoreProperties["storePassword"] as String?
        }
    }
''';

const _ktsReleaseSigning =
    '''            signingConfig = if (keystorePropertiesFile.exists()) {
                signingConfigs.getByName("release")
            } else {
                logger.warn("WARNING: android/key.properties missing - release is DEBUG-signed and cannot be uploaded to Google Play.")
                signingConfigs.getByName("debug")
            }''';
